// 2. Расширение протокола: поведение по умолчанию
extension Message {
    var isSilent: Bool {
        return false
    }

    func notificationText() -> String {
        return "\(sender): \(preview())"
    }
}

struct TextMessage: Message {
    let sender: String
    let text: String

    func preview() -> String {
        return text
    }
}

struct PhotoMessage: Message {
    let sender: String
    let caption: String

    func preview() -> String {
        return caption.isEmpty ? "Фото" : "Фото: \(caption)"
