```

Протоколы готовы. Заполни пропуски:

```swift
protocol Downloadable {
    var fileSizeKB: Int { get }
}

protocol Editable: Message {
    mutating func edit(to newText: String)
}

extension TextMessage: Editable {
    mutating func edit(to newText: String) {
